sealed class Either<out L, out R> {
    data class Left<out A>(val reason: A) : Either<A, Nothing>()
    data class Right<out B>(val value: B) : Either<Nothing, B>()
}

fun label(result: Either<String, Int>): String = when (result) {
    is Either.Left  -> "failed: ${result.reason}"
    is Either.Right -> "ok: ${result.value}"          // no else arm needed
}
